164 |   164 |     const now = Date.now();
165 |   165 |     for (const [key, entry] of this.listCache.entries()) {
166 |   166 |       if (now - entry.timestamp > this.cacheConfig.ttl) {
167 |   167 |         this.listCache.delete(key);
168 |   168 |       }
169 |   169 |     }
