179 |   179 |   /**
180 |   180 |    * Obtém itens do cache se válidos.
181 |   181 |    */
182 |   182 |   private getCachedItems(folderId: string | null): DriveItem[] | null {
183 |   183 |     this.cleanExpiredCache();
184 |   184 |     const key = this.cacheKey(folderId);
185 |   185 |     const entry = this.listCache.get(key);
186 |   186 |     if (!entry) return null;
187 |   187 |     if (Date.now() - entry.timestamp > this.cacheConfig.ttl) {
188 |   188 |       this.listCache.delete(key);
189 |   189 |       return null;
190 |   190 |     }
191 |   191 |     return entry.items;
192 |   192 |   }
